create role anon;create role authenticated;create schema auth;create schema private;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table organizations(id uuid primary key);
create table profiles(id uuid primary key);
create table organization_members(organization_id uuid,user_id uuid,role text,status text,access_role_id uuid);
create table organization_access_roles(id uuid primary key,organization_id uuid,capabilities text[],deleted_at timestamptz);
create function private.is_active_member(o uuid) returns boolean language sql stable security definer as $$select exists(select 1 from public.organization_members where organization_id=o and user_id=auth.uid() and status='active')$$;
create function private.is_org_manager(o uuid) returns boolean language sql stable security definer as $$select exists(select 1 from public.organization_members where organization_id=o and user_id=auth.uid() and role in ('admin','board') and status='active')$$;
create function private.can_manage_events(o uuid) returns boolean language sql stable as $$select private.is_org_manager(o)$$;
create function private.can_manage_projects(o uuid) returns boolean language sql stable as $$select private.is_org_manager(o)$$;
create function private.can_manage_finance(o uuid) returns boolean language sql stable as $$select private.is_org_manager(o)$$;
grant usage on schema auth,private to authenticated;
grant select on organization_members,organization_access_roles to authenticated;
create table projects(id uuid primary key,organization_id uuid,title text,status text default 'active',start_date date,due_date date,deleted_at timestamptz);
create unique index project_fixture_key on projects(organization_id,id);
create table events(id uuid primary key,organization_id uuid,title text,status text default 'planned',start_at timestamptz,end_at timestamptz,start_date date,end_date date,deleted_at timestamptz);
create unique index event_fixture_key on events(organization_id,id);
create table community_people(id uuid primary key,organization_id uuid,deleted_at timestamptz);
create table partners(id uuid primary key,organization_id uuid,name text,contract_url text,created_by uuid);
create table campaigns(id uuid primary key,organization_id uuid);
create table tasks(id uuid primary key,organization_id uuid,title text,description text,status text default 'todo',priority text,due_at timestamptz,project_id uuid,content_id uuid,created_by uuid,created_at timestamptz default now(),updated_at timestamptz default now(),completed_at timestamptz,deleted_at timestamptz);
create table expenses(id uuid primary key,organization_id uuid,title text,proof_url text,declaration_url text,created_by uuid);
create table income_entries(id uuid primary key,organization_id uuid,title text,proof_url text,created_by uuid);
create table meetings(id uuid primary key,organization_id uuid,title text,minutes_url text,created_by uuid);
create table administrative_documents(id uuid primary key,organization_id uuid,title text,drive_url text,created_by uuid);
grant select,insert,update,delete on tasks,events,projects to authenticated;
alter table tasks enable row level security;
create policy fixture_tasks on tasks to authenticated using(private.is_active_member(organization_id)) with check(private.is_org_manager(organization_id));
create table dossier_choice_options(organization_id uuid,set_key text,value text,label text,primary key(organization_id,set_key,value));
create function private.fixture_choice_guard() returns trigger language plpgsql as $$begin return new;end$$;
create trigger guard_dossier_choice_option before update on dossier_choice_options for each row execute function private.fixture_choice_guard();
create function private.dossier_choice_catalog() returns jsonb language sql as $$select '[{"key":"assets.asset_type","values":[{"value":"equipment","label":"equipment"}]}]'::jsonb$$;

create function private.can_manage_content(o uuid) returns boolean language sql stable as $$select private.is_org_manager(o)$$;

alter table projects add column drive_url text;
alter table events add column drive_url text;
alter table campaigns add column drive_url text;
alter table community_people add column drive_url text;
create table knowledge_articles(id uuid primary key,organization_id uuid,title text,drive_url text,created_by uuid);
create table content_items(id uuid primary key,organization_id uuid,title text,drive_url text,canva_url text,publication_url text,created_by uuid);
create table merch_launches(id uuid primary key,organization_id uuid,title text,drive_url text,created_by uuid);
